package com.vitalminds.controller;
import com.vitalminds.model.*; import com.vitalminds.repository.*; import com.vitalminds.service.*; import org.springframework.security.core.Authentication; import org.springframework.stereotype.Controller; import org.springframework.ui.Model; import org.springframework.web.bind.annotation.*; import java.util.*;
@Controller public class DashboardController {
 private final UserService users; private final HealthRecordRepository records; private final GoalRepository goals; private final ReminderRepository reminders; private final MedicationRepository meds; private final ActivityLogRepository activity; private final SleepLogRepository sleep; private final AppointmentRepository appointments; private final HydrationLogRepository hydration; private final MealLogRepository meals; private final WorkoutPlanRepository workouts; private final HealthAlertRepository alerts; private final HealthInsightsService insights;
 public DashboardController(UserService u,HealthRecordRepository r,GoalRepository g,ReminderRepository rem,MedicationRepository m,ActivityLogRepository a,SleepLogRepository s,AppointmentRepository ap,HydrationLogRepository h,MealLogRepository ml,WorkoutPlanRepository w,HealthAlertRepository al,HealthInsightsService i){users=u;records=r;goals=g;reminders=rem;meds=m;activity=a;sleep=s;appointments=ap;hydration=h;meals=ml;workouts=w;alerts=al;insights=i;}
 private User user(Authentication a){return users.findByEmail(a.getName()).orElseThrow();}
 @GetMapping("/dashboard") public String dashboard(Authentication auth,Model model){User u=user(auth);var rs=records.findTop20ByUserIdOrderByUploadedAtDesc(u.getId());var acts=activity.findTop14ByUserIdOrderByDateDesc(u.getId());var sl=sleep.findTop14ByUserIdOrderByDateDesc(u.getId());var latest=rs.isEmpty()?null:rs.get(0);int score=insights.score(u,latest,acts,sl);model.addAttribute("user",u);model.addAttribute("records",rs);model.addAttribute("latest",latest);model.addAttribute("score",score);model.addAttribute("scoreLabel",score>=85?"Excellent":score>=70?"Good":score>=55?"Needs attention":"Needs review");model.addAttribute("advice",insights.recommendations(u,latest,acts,sl).get(0));model.addAttribute("recommendations",insights.recommendations(u,latest,acts,sl));model.addAttribute("goals",goals.findTop6ByUserIdOrderByCreatedAtDesc(u.getId()));model.addAttribute("reminders",reminders.findTop8ByUserIdAndActiveTrueOrderByReminderTimeAsc(u.getId()));model.addAttribute("medications",meds.findTop8ByUserIdAndActiveTrueOrderByNameAsc(u.getId()));model.addAttribute("profileComplete",u.getAge()!=null&&u.getHeightCm()!=null&&u.getWeightKg()!=null);model.addAttribute("activityLogs",acts);model.addAttribute("sleepLogs",sl);model.addAttribute("appointments",appointments.findTop6ByUserIdOrderByAppointmentAtAsc(u.getId()));model.addAttribute("hydrationLogs",hydration.findTop14ByUserIdOrderByDateDesc(u.getId()));model.addAttribute("mealLogs",meals.findTop12ByUserIdOrderByDateDesc(u.getId()));model.addAttribute("workoutPlans",workouts.findTop10ByUserIdOrderByDateDesc(u.getId()));model.addAttribute("alerts",alerts.findTop8ByUserIdOrderByCreatedAtDesc(u.getId()));model.addAttribute("unreadAlerts",alerts.countByUserIdAndReadFlagFalse(u.getId()));return "dashboard";}
 @PostMapping("/api/profile") public String update(Authentication a,@RequestParam String name,@RequestParam(required=false)Integer age,@RequestParam(required=false)String gender,@RequestParam(required=false)Double heightCm,@RequestParam(required=false)Double weightKg,@RequestParam(required=false)String goal){User u=user(a);u.setName(name);u.setAge(age);u.setGender(gender);u.setHeightCm(heightCm);u.setWeightKg(weightKg);u.setGoal(goal);users.save(u);return "redirect:/dashboard?profileSaved";}
 @GetMapping("/api/health-data") @ResponseBody public Map<String,Object> data(Authentication a){User u=user(a);var list=records.findTop20ByUserIdOrderByUploadedAtAsc(u.getId());List<String> labels=new ArrayList<>();List<Double> glucose=new ArrayList<>(),bmi=new ArrayList<>();List<Integer> sys=new ArrayList<>();for(var r:list){labels.add(r.getUploadedAt().toLocalDate().toString());glucose.add(r.getGlucose());bmi.add(r.getBmi());sys.add(r.getSystolic());}return Map.of("labels",labels,"glucose",glucose,"bmi",bmi,"systolic",sys);}
}
